import std/deques

proc rotate[T](items: seq[T], n: int): seq[T] =
  if items.len == 0: return @[]

  var d: Deque[T] = initDeque[T]()
  for item in items: d.addLast(item)

  # Calculate effective rotations, ensuring a positive result
  let numRotations = (n mod d.len + d.len) mod d.len

  for _ in 0..<numRotations:
    d.addLast(d.popFirst())

  # Convert the deque back to a sequence
  result = newSeq[T](d.len)
  var i = 0
  while d.len > 0:
    result[i] = d.popFirst()
    inc(i)

