proc evaluateFactor(factor: string): int =
  let factor = factor.strip()
  if factor.startsWith('(') and factor.endsWith(')'):
    return evaluateExpr(factor[1..^2])
  else:
    return factor.parseInt()

proc evaluateTerm(term: string): int =
  var result = 0
  var current = ""
  var op = '*'
  var i = 0

  while i < term.len:
    if term[i] in "*/":
      let factor = current.strip()
      let nextFactor = evaluateFactor(factor)
      if result == 0:
        result = nextFactor
      else:
        if op == '*':
          result *= nextFactor
        else:
          result = result div nextFactor
      op = term[i]
      current = ""
    else:
      current &= term[i]
    inc i

  let factor = current.strip()
  if factor.len > 0:
    let nextFactor = evaluateFactor(factor)
    if result == 0:
      result = nextFactor
    else:
      if op == '*':
        result *= nextFactor
      else:
        result = result div nextFactor

  return result

proc evaluateExpr(expr: string): int =
  var result = 0
  var current = ""
  var op = '+'
  var i = 0
  var parenDepth = 0

  while i < expr.len:
    if expr[i] == '(':
      inc parenDepth
      current &= expr[i]
    elif expr[i] == ')':
      dec parenDepth
      current &= expr[i]
    elif expr[i] in "+-" and parenDepth == 0:
      let term = current.strip()
      let nextTerm = evaluateTerm(term)
      if result == 0:
        result = nextTerm
      else:
        if op == '+':
          result += nextTerm
        else:
          result -= nextTerm
      op = expr[i]
      current = ""
    else:
      current &= expr[i]
    inc i

  let term = current.strip()
  if term.len > 0:
    let nextTerm = evaluateTerm(term)
    if result == 0:
      result = nextTerm
    else:
      if op == '+':
        result += nextTerm
      else:
        result -= nextTerm

  return result

