import std/[json, times, strutils, base64, hmac, sha256]

# Reimplementing base64UrlEncode and base64UrlDecode for educational purposes,
# as Nim's stdlib `base64` module does not directly provide URL-safe variants.
proc base64UrlEncode(data: string): string =
  var encoded = encode(data)
  encoded = encoded.replace("=", "").replace("+", "-").replace("/", "_")
  return encoded

proc base64UrlDecode(data: string): string =
  var padded = data
  let mod4 = data.len mod 4
  if mod4 > 0:
    padded.add(repeat('=', 4 - mod4))
  padded = padded.replace("-", "+").replace("_", "/")
  return decode(padded)

proc generateToken(sub: string, secret: string, expiresInSeconds: int): string =
  let header = %*{"alg": "HS256", "typ": "JWT"}
  let now = epochTime()
  let exp = now + float(expiresInSeconds)
  let payload = %*{"sub": sub, "exp": exp}

  let headerEncoded = base64UrlEncode($header)
  let payloadEncoded = base64UrlEncode($payload)

  let signingInput = headerEncoded & "." & payloadEncoded
  let signatureBytes = hmacSha256(signingInput.toOpenArrayByte(), secret.toOpenArrayByte())
  let signatureEncoded = base64UrlEncode(signatureBytes.toStr())

  return signingInput & "." & signatureEncoded

proc verifyToken(token: string, secret: string): (bool, string) =
  let parts = token.split('.')
  if parts.len != 3:
    return (false, "")

  let (headerEncoded, payloadEncoded, signatureEncoded) = (parts[0], parts[1], parts[2])

  let signingInput = headerEncoded & "." & payloadEncoded
  let expectedSignatureBytes = hmacSha256(signingInput.toOpenArrayByte(), secret.toOpenArrayByte())
  let expectedSignatureEncoded = base64UrlEncode(expectedSignatureBytes.toStr())

  if signatureEncoded != expectedSignatureEncoded:
    return (false, "")

  var payloadJson: JsonNode
  try:
    payloadJson = parseJson(base64UrlDecode(payloadEncoded))
  except:
    return (false, "")

  if not payloadJson.hasKey("exp") or not payloadJson.hasKey("sub"):
    return (false, "")

  let exp = payloadJson["exp"].f
  let now = epochTime()

  if exp < now:
    return (false, "")

  return (true, payloadJson["sub"].s)

