const Port = 9999
const Host = "localhost"

proc sendMessages(s: AsyncSocket) {.async.} =
  while true:
    try:
      let line = stdin.readLine()
      if line.len == 0:
        # User pressed Ctrl+D (EOF) or entered an empty line, signal shutdown
        break
      await s.send(line & "\n")
    except AsyncSocketException as e:
      # Log the error and break, allowing the client to shut down gracefully
      echo "Error sending message: ", e.msg
      break
    except Exception as e:
      echo "Unexpected error in sendMessages: ", e.msg
      break

proc receiveMessages(s: AsyncSocket) {.async.} =
  while true:
    try:
      let msg = await s.recvLine()
      if msg.len == 0:
        # Server closed connection (EOF)
        break
      echo msg
    except AsyncSocketException as e:
      # Log the error and break, allowing the client to shut down gracefully
      echo "Error receiving message: ", e.msg
      break
    except Exception as e:
      echo "Unexpected error in receiveMessages: ", e.msg
      break

proc main() {.async.} =
  let s = newAsyncSocket()
  try:
    await s.connect(Host, Port)
    echo "Connected to server."

    # Send registration
    await s.send("REG nimling\n")
    echo "Sent registration: REG nimling"

    # Start concurrent loops
    let sendFuture = sendMessages(s)
    let receiveFuture = receiveMessages(s)

    # Wait for both tasks to complete. This ensures the program stays alive
    # and exits when both the sending and receiving loops are done.
    # `await allFutures` is used here to block the main async procedure until these
    # futures complete. Since `sendMessages` and `receiveMessages` are
    # designed to exit on EOF or error, this will lead to a clean shutdown.
    await allFutures(sendFuture, receiveFuture)

  except AsyncSocketException as e:
    echo "Connection error: ", e.msg
  except Exception as e:
    echo "An unexpected error occurred: ", e.msg
  finally:
    if s.isOpened():
      s.close()
      echo "Connection closed."

waitFor main()

